function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.cube}"/></svg>`;}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
hydrateIcons();
let design={...DEFAULT_DESIGN},material={...DEFAULT_MATERIAL},experiment={...DEFAULT_EXPERIMENT},print={...DEFAULT_PRINT},graph=null,worker=null,exportWorker=null,state=null,frameNodes=null,frameElements=null,running=false,tab='design',activePreset='canopy',viewer,rebuildTimer,toastTimer;
let recording=new ExperimentRecording(),replayCursor=null,replayPlaying=false,replayRaf=0,replayLastTime=0,recordingImported=false,replayPending=false;
try{viewer=new SpecimenViewer($('#viewport'));}catch(e){viewer=new FlatViewer($('#viewport'));$('#canvas-hint').textContent='2D fallback · Numerical experiments remain available';toast('WebGL2 is unavailable. The studio is using its 2D view.');}
$('#loading').remove();
viewer.getFitFrames=()=>recording.frames;
const movie=new MovieExporter({viewer,download,onRestore:()=>{const s=displayState();if(s)renderState(s,replayCursor!==null);updateDisplacementControls();}});
const experimentStore=new ExperimentStore();
const resultRecorder=new ExperimentRecorder(experimentStore,()=>({recording,metadata:recordingMetadata(),state}),saved=>{
  $('#results-save-state').textContent=saved.persistent?'Experiment auto-saved':'Results saved in this tab only';
  $('#results-save-state').title=saved.persistent?'Open Results to compare, replay, or export experiments.':experimentStore.warning;
  resultsUI.refresh();window.dispatchEvent(new CustomEvent('canopy:experiment-saved',{detail:saved}));
});
const resultsUI=new ResultsUI({store:experimentStore,recorder:resultRecorder,download,toast,onReplay:loadSavedReplay,onClear:()=>rebuild()});

function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function download(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const fmt=(n,d=2)=>Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
function range(key,label,min,max,step,value,display,left='',right='',scope='design'){return `<div class="control"><label for="c-${key}">${label}<output data-output="${key}">${display}</output></label><input type="range" id="c-${key}" data-key="${key}" data-scope="${scope}" min="${min}" max="${max}" step="${step}" value="${value}"><div class="range-ends"><span>${left}</span><span>${right}</span></div></div>`;}
function number(key,label,min,max,step,value,scope){return `<div class="control"><label for="c-${key}">${label}</label><input type="number" id="c-${key}" data-key="${key}" data-scope="${scope}" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;}
function select(key,label,options,value,scope='design'){if(!options.some(([v])=>v===String(value))){let label=String(value)+' · Custom';if(['maxTriangles','maxGridPoints'].includes(key))label=fmt(+value/1e6,1)+' million · Custom';if(key==='targetRatio')label=fmt(+value*100,1)+'% · Custom';options=[...options,[String(value),label]];}return `<div class="control"><label for="c-${key}">${label}</label><select class="select" id="c-${key}" data-key="${key}" data-scope="${scope}">${options.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function section(title,body,detail=''){return `<section class="control-section"><h2 class="control-heading">${title}<span>${detail}</span></h2>${body}</section>`;}
function controls(){
  const el=$('#controls'),is3D=design.dimension==='3d';
  if(tab==='design')el.innerHTML=
    section('Unit cell',select('dimension','Design space',[['3d','3D spatial cell'],['2d','2D planar network']],design.dimension))+
    section('Cell architecture',select('family','Topology',is3D?[['cellular','Organic Kelvin foam'],['honeycomb','Ordered Kelvin cell'],['branches','Spatial venation'],['reentrant','Re-entrant cage'],['triangular','Octet truss'],['diamond','Diamond lattice']]:[['cellular','Organic cellular'],['honeycomb','Ordered honeycomb'],['branches','Branching venation'],['reentrant','Re-entrant cells'],['triangular','Triangulated lattice']],design.family)+range('disorder','Disorder',0,1,.01,design.disorder,Math.round(design.disorder*100)+'%','Ordered','Organic')+`<div class="two-controls">${number('columns',is3D?'Cells X':'Columns',is3D?1:3,is3D?4:9,1,design.columns,'design')}${number('rows',is3D?'Cells Y':'Rows',is3D?1:3,is3D?4:10,1,design.rows,'design')}</div>`+(is3D?number('slices','Cells Z',1,4,1,design.slices,'design'):''), '01')+
    section('Hierarchy',`<div class="hierarchy-buttons">${[0,1,2].map(i=>`<button data-level="${i}" class="${design.hierarchy===i?'active':''}">${i===0?'1':i===1?'2':'3'}<small>${i===0?'Primary':i===1?'Nested':'Deep'}</small></button>`).join('')}</div>`+range('hierarchyScale','Pore scale ratio',.28,.65,.01,design.hierarchyScale,fmt(design.hierarchyScale),'Fine','Open')+range('fineRatio','Branch thickness ratio',.35,.85,.01,design.fineRatio,fmt(design.fineRatio),'Delicate','Robust'), '02')+
    section('Dimensions & direction',range('width','Tile width',20,160,1,design.width,fmt(design.width,0)+' mm')+(is3D?range('height','Tile height · Y',12,160,1,design.height,fmt(design.height,0)+' mm')+range('depth','Tile depth · Z',12,160,1,design.depth,fmt(design.depth,0)+' mm'):'')+range('radius','Primary strut radius',.25,1.8,.01,design.radius,fmt(design.radius)+' mm')+range('anisotropy','Horizontal stretch',.5,1.8,.02,design.anisotropy,fmt(design.anisotropy)+'×'), '03')+
    section('Grading & assembly',select('gradientAxis','Gradient direction',[['y','Bottom → top'],['x','Left → right'],...(is3D?[['z','Back → front']]:[]),['radial','Center → boundary']],design.gradientAxis)+range('gradient','Thickness gradient',-.8,.8,.02,design.gradient,(design.gradient>0?'+':'')+fmt(design.gradient), 'Reverse','Forward')+`<div class="two-controls">${number('repeatsX','Repeat X',1,3,1,design.repeatsX,'design')}${number('repeatsY','Repeat Y',1,3,1,design.repeatsY,'design')}</div>`+(is3D?number('repeatsZ','Repeat Z',1,3,1,design.repeatsZ,'design'):'')+`<p class="control-note">Shared face nodes join repeats into one ${is3D?'spatial':'planar'} mechanical specimen.</p>`, '04')+
    `<button class="reference-card" id="reference-card"><img src="./assets/reference.png" alt="Provided cellular reference"><span><strong>Inspired by living architecture</strong><small>View reference & interpretation ↗</small></span></button>`;
  if(tab==='experiment')el.innerHTML=
    section('Constitutive behavior',select('model','Material class',[['linear','Linear elastic'],['neo','Neo-Hookean axial'],['plastic','Elastoplastic axial']],material.model,'material')+`<p class="control-note">${material.model==='neo'?'Nonlinear incompressible axial response; reference-section elastic bending.':material.model==='plastic'?'Irreversible axial deformation with isotropic hardening; elastic bending.':'Linear elastic material with large-rotation beam kinematics.'}</p>`+number('E','Young’s modulus · MPa',.1,250000,.1,material.E,'material')+(is3D?number('poisson','Poisson ratio · torsional stiffness',-.5,.49,.01,material.poisson,'material'):''))+
    (material.model==='plastic'?section('Plasticity',number('yieldStress','Initial yield stress · MPa',.01,5000,.1,material.yieldStress,'material')+range('hardening','Post-yield tangent / E',.001,.3,.001,material.hardening,fmt(material.hardening,3),'Softening resistance','Hardening','material')):'')+
    section('Member fracture',`<label class="switch-label"><span><strong>Allow brittle failure</strong><small>${is3D?'Axial + bending + torsional stress':'Tensile + bending stress criterion'}</small></span><input type="checkbox" id="fracture-toggle" role="switch" ${material.fracture?'checked':''}></label>`+number('strength','Tensile strength · MPa',.01,10000,.1,material.strength,'material')+`<p class="control-note">Failure removes one whole strut and resolves equilibrium. This strength criterion is not a calibrated toughness law.</p>`)+
    section('Numerical resolution',select('subdivisions','Elements per strut',[['1','1 · Fast exploration'],['2','2 · Balanced'],['3','3 · Refined']],String(experiment.subdivisions),'experiment')+select('increment','Strain increment',[['0.0005','0.05% · Fine'],['0.001','0.10%'],['0.002','0.20% · Default'],['0.005','0.50% · Fast']],String(experiment.increment),'experiment')+`<p class="control-note">Compare element counts and load increments when interpreting buckling or fracture. Changing a material or resolution resets the experiment.</p>`)+
    `<div class="warning-note">Illustrative material constants. Calibrate modulus, strength, and hardening for your printed specimens.</div>`;
  if(tab==='fabrication')el.innerHTML=
    section('Thickening strategy',select('profile','Cross-section & joints',[['round','Circular struts'],['nodes','Reinforced junctions'],['ribbon',is3D?'Square-section struts':'Flat ribbon struts']],print.profile,'print')+range('thickening','Radius multiplier',.6,2.8,.05,print.thickening,fmt(print.thickening)+'×','Slender','Thick','print')+number('minDiameter','Minimum diameter · mm',.3,5,.1,print.minDiameter,'print'))+
    section('Print dimensions',number('outputWidth','Nominal network width · mm',20,240,1,print.outputWidth,'print')+(is3D?`<p class="control-note">The complete spatial unit cell is exported. Assemble it along X, Y, and Z in Structure; those repeats are included in mechanics.</p>`:`<div class="two-controls">${number('layers','Layers',1,4,1,print.layers,'print')}${number('layerSpacing','Spacing · mm',.5,15,.5,print.layerSpacing,'print')}</div><p class="control-note">Layers are connected by through-thickness struts. Layering is for fabrication; mechanics remains in-plane.</p>`))+
    section('Surface quality',number('voxel','Starting voxel size · mm',.06,1,.01,print.voxel,'print')+`<label class="switch-label" style="margin-top:20px"><span><strong>Use deformed shape</strong><small>Exports the selected replay or solver state</small></span><input type="checkbox" id="deformed-toggle" role="switch" ${print.deformed?'checked':''}></label><p class="control-note">Closed union mesh in mm. Grid resolution limits accuracy. Thickening is applied after the mechanical experiment.</p>`)+
    section('Adaptive simplification',`<label class="switch-label"><span><strong>Simplify smooth surfaces</strong><small>Retain detail within an error target</small></span><input id="simplify-toggle" type="checkbox" role="switch" ${print.simplify?'checked':''}></label>`+select('targetRatio','Target remaining triangles',[['0.1','10% · Maximum reduction'],['0.2','20% · Default'],['0.4','40%'],['0.7','70%']],String(print.targetRatio),'print')+number('surfaceError','Surface error target · mm',.001,1,.005,print.surfaceError,'print')+select('normalWeight','Curvature retention',[['0','Position only'],['1','Curvature-aware · Default'],['2','Strong curvature retention']],String(print.normalWeight),'print')+`<label class="switch-label"><span><strong>Protect junctions & tips</strong><small>Keep vertices near branch connections</small></span><input id="protect-junctions-toggle" type="checkbox" role="switch" ${print.protectJunctions?'checked':''}></label><p class="control-note">Reduction stops when the error target or feature protection is reached, even if more triangles remain. Error is a simplifier estimate, not a guaranteed maximum surface deviation. The target is capped at 10% of the thinnest diameter.</p>`)+
    section('Mesh budgets',select('maxTriangles','Raw triangle limit',[['2000000','2 million'],['4000000','4 million'],['8000000','8 million · Default'],['12000000','12 million'],['16000000','16 million']],String(print.maxTriangles),'print')+select('maxGridPoints','Grid sample budget',[['22000000','22 million · Legacy'],['64000000','64 million'],['128000000','128 million · Default'],['256000000','256 million'],['512000000','512 million']],String(print.maxGridPoints),'print')+`<p class="control-note">Budgets apply before simplification. Larger limits need more time and memory. An unsimplified 16M-triangle STL is 800 MB. The volume is processed in slices to reduce memory use.</p>`)+
    `<div class="print-summary"><strong id="print-size">Preparing print preview</strong><span id="print-detail"></span></div><button class="button primary full" style="margin-top:16px" id="export-panel">${icon('download')}Generate STL</button><p class="control-note">Validate supports, wall dimensions, and machine limits in your slicer. Disconnected pieces are reported at export.</p>`;
  hydrateIcons(el);
  if(tab==='design'){
    if(design.family==='honeycomb')$('#c-disorder').disabled=true;
    if(design.hierarchy===0){$('#c-hierarchyScale').disabled=true;$('#c-fineRatio').disabled=true;}
  }
  if(is3D&&material.model==='neo'&&$('#c-poisson')){$('#c-poisson').value=.5;$('#c-poisson').disabled=true;}
  el.querySelectorAll('[data-key]').forEach(input=>input.addEventListener(input.type==='range'?'input':'change',()=>{
    const {key,scope}=input.dataset,obj=scope==='design'?design:scope==='material'?material:scope==='experiment'?experiment:print;
    let value=input.tagName==='SELECT'&&['dimension','family','gradientAxis','model','profile'].includes(key)?input.value:Number(input.value);
    if(typeof value==='number'){const lo=+input.min,hi=+input.max;if(!Number.isFinite(value)){input.value=obj[key];return;}if(input.hasAttribute('min'))value=Math.max(lo,value);if(input.hasAttribute('max'))value=Math.min(hi,value);input.value=value;}
    obj[key]=value;
    const out=el.querySelector(`[data-output="${key}"]`);if(out)out.textContent=key==='disorder'?Math.round(value*100)+'%':['width','height','depth'].includes(key)?fmt(value,0)+' mm':key==='radius'?fmt(value)+' mm':['anisotropy','thickening'].includes(key)?fmt(value)+'×':fmt(value,key==='hardening'?3:2);
    if(scope==='print'){updatePrint();return;}
    if(key==='dimension'){design.columns=value==='3d'?1:5;design.rows=value==='3d'?1:6;design.slices=1;design.repeatsX=design.repeatsY=design.repeatsZ=1;if(value==='3d'){design.height=design.depth=design.width;}else{experiment.axis='y';experiment.shearAxis='x';if(design.family==='diamond')design.family='cellular';}}
    if(key==='family'&&value==='honeycomb')design.disorder=0;
    if(scope==='design'){activePreset='';updatePresetSelection();}
    clearTimeout(rebuildTimer);rebuildTimer=setTimeout(()=>{if(['dimension','family','model'].includes(key))controls();rebuild();},input.type==='range'?160:0);
  }));
  el.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{design.hierarchy=+b.dataset.level;activePreset='';controls();updatePresetSelection();rebuild();});
  $('#reference-card')?.addEventListener('click',openReference);
  $('#fracture-toggle')?.addEventListener('change',e=>{material.fracture=e.target.checked;rebuild();});
  $('#simplify-toggle')?.addEventListener('change',e=>{print.simplify=e.target.checked;controls();});
  $('#protect-junctions-toggle')?.addEventListener('change',e=>{print.protectJunctions=e.target.checked;});
  if(tab==='fabrication')for(const key of ['targetRatio','surfaceError','normalWeight'])$('#c-'+key).disabled=!print.simplify;
  $('#deformed-toggle')?.addEventListener('change',e=>{print.deformed=e.target.checked;updatePrint();});
  $('#export-panel')?.addEventListener('click',startExport);
  if(tab==='fabrication'&&graph)updatePrint();
}
function setTab(t){if(t==='fabrication')stopPlayback();tab=t;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));controls();if(t!=='fabrication'&&graph){viewer.setGraph(graph);viewer.setExperiment(experiment);if(frameNodes)viewer.setFrame(frameNodes,frameElements);viewer.update(displayState());$('#geometry-badge').textContent=replayCursor!==null?'Experiment replay':state&&state.strain>0?'Deformed specimen':'Design geometry';}else if(t==='fabrication'&&graph)updatePrint();updateReplay();updateDisplacementControls();if(t!=='fabrication'&&viewer.displacementScale>1)viewer.fit(true,true);}
function updatePrint(){if(!graph)return;try{const shown=displayState(),spec=printPrimitives(graph,print,frameElements&&shown?{...shown,elements:frameElements}:null);viewer.setPrint(spec);$('#slice-button').classList.remove('active');$('#cutaway-control').hidden=true;const dims=spec.bounds.max.map((x,i)=>x-spec.bounds.min[i]);if($('#print-size'))$('#print-size').textContent=dims.map(n=>fmt(n,1)).join(' × ')+' mm';if($('#print-detail'))$('#print-detail').textContent=`${spec.segments.length.toLocaleString()} fused primitives · ${fmt(spec.minDiameter,2)} mm minimum diameter · ${fmt(estimatePrintGrid(spec,print.voxel).total/1e6,1)}M grid samples`;$('#geometry-badge').textContent='Print geometry preview';$('#specimen-size').textContent=dims.map(n=>fmt(n,1)).join(' × ')+' mm';}catch(e){toast(e.message);}}
function presets(){const container=$('#presets');container.innerHTML='';for(const p of PRESETS){const g=generateNetwork({...p.settings,columns:1,rows:1,slices:1,width:25,height:25,depth:25,repeatsX:1,repeatsY:1,repeatsZ:1,hierarchy:Math.min(1,p.settings.hierarchy)}),project=n=>[n.x+.5*(n.z||0),g.height-n.y+.3*(n.z||0)],path=g.edges.map(e=>{const a=project(g.nodes[e.a]),b=project(g.nodes[e.b]);return `M${a[0].toFixed(2)},${a[1].toFixed(2)}L${b[0].toFixed(2)},${b[1].toFixed(2)}`;}).join(' ');const b=document.createElement('button');b.className='preset';b.dataset.preset=p.id;b.title=p.name+' · '+p.detail;b.innerHTML=`<svg viewBox="-1 -1 ${g.width+.5*g.depth+2} ${g.height+.3*g.depth+2}" aria-hidden="true"><path d="${path}"/></svg><strong>${p.name}</strong><small>${p.detail}</small>`;b.onclick=()=>{design={...p.settings};activePreset=p.id;updatePresetSelection();setTab('design');rebuild();};container.append(b);}updatePresetSelection();}
function updatePresetSelection(){$$('[data-preset]').forEach(b=>b.classList.toggle('active',b.dataset.preset===activePreset));}
function rebuild(saved=null){
  clearTimeout(rebuildTimer);rebuildTimer=null;
  replayPending=false;
  resultRecorder.end(running);
  try{design=sanitizeDesign(design);graph=saved?.metadata.graph||generateNetwork(design);stopPlayback();replayCursor=null;recording=saved?.recording||new ExperimentRecording();recordingImported=!!saved;worker?.terminate();worker=null;if(!saved){worker=new Worker(new URL('./simulation-worker.js',import.meta.url),{type:'module'});const owner=worker;worker.onmessage=e=>{if(worker===owner)onWorker(e);};worker.onerror=e=>{if(worker!==owner)return;running=false;replayPending=false;resultRecorder.status('error');updateRun();toast('The solver could not start. Run the app through its local server, not a file:// URL.');};}state=null;frameNodes=null;frameElements=null;running=false;viewer.setGraph(graph);viewer.setExperiment(experiment);
    const count=graph.stats;$('#network-count').textContent=`${count.nodes.toLocaleString()} / ${count.edges.toLocaleString()}`;$('#min-diameter').textContent=fmt(2*count.minRadius)+' mm';$('#connectivity').textContent=count.connected?'Selected faces connected':'No spanning load path';$('#connectivity').style.color=count.connected?'':'#a56748';$('#specimen-size').textContent=[graph.width,graph.height,...(graph.dimension===3?[graph.depth]:[])].map(x=>fmt(x,1)).join(' × ')+' mm';$('#spatial-metrics').hidden=graph.dimension!==3;$('#notch-z-control').hidden=graph.dimension!==3;$('#axis-controls').hidden=graph.dimension!==3;$('#model-scope').textContent=graph.dimension===3?'3D beam mechanics · Bending + torsion':'In-plane beam mechanics · Large rotations';$('#load-axis').value=experiment.axis;$('#shear-axis').value=experiment.shearAxis;$('#shear-axis-control').hidden=experiment.mode!=='shear';$('#notch-z').value=design.notchZ*100;$('#notch-z-output').textContent=Math.round(design.notchZ*100)+'% of depth';
    $('#notch-toggle').checked=design.notch;$('#notch-settings').hidden=!design.notch;$('#notch-depth').value=design.notchDepth*100;$('#notch-depth-output').textContent=Math.round(design.notchDepth*100)+'% of width';$('#notch-y').value=design.notchY*100;$('#notch-y-output').textContent=Math.round(design.notchY*100)+'%';$('#seed-label').textContent='#'+String(design.seed).padStart(4,'0');
    const name=PRESETS.find(p=>p.id===activePreset)?.name||'Custom';$('#model-title').innerHTML=esc(name)+' <span>/ '+(graph.dimension===3?(design.hierarchy?'hierarchical 3D cell':'3D unit cell'):(design.hierarchy?'hierarchical network':'cellular network'))+'</span>';$('#design-name').textContent=design.family==='branches'?'Branching cellular solid':design.family==='reentrant'?'Re-entrant cellular solid':'Hierarchical cellular solid';$('#geometry-badge').textContent='Design geometry';
    resetReadout();if(saved){frameNodes=saved.metadata.nodes;frameElements=saved.metadata.elements;const last=recording.frames.at(-1);state={...last,history:(saved.metadata.history||[]).slice(0,last.historyCount)};viewer.setFrame(frameNodes,frameElements);replayCursor=0;renderState(displayState(),true);if(viewer.displacementScale>1)viewer.fit(true,true);}else worker.postMessage({type:'init',graph,material,experiment});updateRun();updateReplay();updateDisplacementControls();drawChart();if(tab==='fabrication')updatePrint();
    if(graph.edges.length>6500)toast('Large specimen: experiments may take longer. Use one element per strut for initial exploration.');
  }catch(e){if(graph){design={...graph.design};controls();}toast('Could not generate the specimen: '+e.message);}
}
