function stopPlayback(){replayPlaying=false;cancelAnimationFrame(replayRaf);replayRaf=0;}
function updateReplay(){
  const count=recording.frames.length,available=count>0&&!running&&!replayPending&&!movie.busy,position=replayCursor??Math.max(0,count-1);
  $('#replay-play').disabled=count<2||replayPending||movie.busy;
  $('#replay-timeline').disabled=!available||count<2;
  $('#replay-prev').disabled=!available||position<=0;
  $('#replay-next').disabled=!available||position>=count-1;
  $('#movie-open').disabled=!available||count<2;
  $('#save-replay').disabled=!available;
  $('#replay-live').hidden=replayCursor===null||recordingImported;
  $('#replay-live').disabled=replayCursor===null||recordingImported||replayPending||movie.busy;
  $('#replay-new').hidden=!recordingImported;$('#replay-new').disabled=movie.busy;
  $('#replay-mode').textContent=recordingImported?'Saved replay':replayCursor!==null?'Current experiment replay':running?'Live · recording':'Live experiment';
  $('#replay-timeline').max=Math.max(0,count-1);$('#replay-timeline').value=Math.floor(position);
  $('#replay-position').textContent=`${count?Math.floor(position)+1:0} / ${count}`;
  const action=replayPending?'Pausing…':running?'Pause to replay':replayPlaying?'Pause replay':'Play replay';
  $('#replay-play').innerHTML=icon(replayPlaying?'pause':'play')+action;
  const reason=replayPending?'Waiting for the solver to pause.':count<2?(recordingImported?'This recording has only one state; there is no motion to play.':'Replay needs at least one recorded load step.'):movie.busy?'Finish or cancel the MP4 export first.':running?'Pause the experiment and play its recorded steps.':replayPlaying?'Pause playback.':'Play the recorded experiment; at the end, play again to restart.';
  $('#replay-play').title=reason;
  const prefix=recording.full?'Recording limit reached · saved portion only. ':'';
  const frame=replayCursor===null?null:sampleRecording(recording.frames,replayCursor,$('#replay-smooth').checked);
  const guidance=replayPending?reason:count<2?(recordingImported?reason:'Run an experiment to record its load steps, or open an earlier recording from Results.'):running?'Recording load steps. Click Pause to replay to stop the solve and watch them.':replayPlaying?'Playing recorded steps.':replayCursor!==null?'Click Play replay to watch, or drag the timeline to inspect a state.':`${count.toLocaleString()} recorded states ready. Click Play replay to watch this experiment.`;
  const detail=frame?.kind==='fracture'?' Strut removed; equilibrium pending.':frame?.interpolated?' Interpolated geometry; readouts hold the preceding state.':frame?' Playback time is not physical time.':'';
  $('#replay-status').textContent=prefix+guidance+detail;
}
