$('#open-replay').onclick=()=>$('#replay-input').click();
function loadSavedReplay(saved){
  resultRecorder.end(running);design=sanitizeDesign(saved.metadata.design);material={...DEFAULT_MATERIAL,...saved.metadata.material};experiment={...DEFAULT_EXPERIMENT,...saved.metadata.experiment};print={...DEFAULT_PRINT,...saved.metadata.print};activePreset='';tab='experiment';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===experiment.mode));$('#target').value=experiment.target*100;$('#target-output').textContent=fmt(experiment.target*100,1)+'%';controls();updatePresetSelection();rebuild(saved);if(recording.frames.length>1)$('#replay-play').focus();toast('Saved replay opened. Click Play replay to watch it. New experiment starts a fresh solve from this design.');
}
$('#replay-input').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>144*1048576)throw Error('Replay files must be smaller than 144 MiB.');loadSavedReplay(decodeRecording(await file.arrayBuffer()));}catch(error){toast(error.message);}e.target.value='';};
$('#movie-open').onclick=()=>{try{if(running)return;stopPlayback();if(tab==='fabrication')setTab('experiment');if(replayCursor===null)replayCursor=recording.frames.length-1;renderState(displayState(),true);updateReplay();movie.open(recording.frames,recordingMetadata());}catch(error){toast(error.message);}};
$('#target').value=experiment.target*100;$('#target-output').textContent=fmt(experiment.target*100,1)+'%';controls();presets();rebuild();

$('#load-axis').onchange=e=>{experiment.axis=e.target.value;if(experiment.shearAxis===experiment.axis)experiment.shearAxis=experiment.axis==='x'?'z':'x';rebuild();};
$('#shear-axis').onchange=e=>{if(e.target.value===experiment.axis){e.target.value=experiment.shearAxis;toast('Choose a shear direction perpendicular to the load axis.');return;}experiment.shearAxis=e.target.value;rebuild();};
$('#notch-z').oninput=e=>{design.notchZ=+e.target.value/100;$('#notch-z-output').textContent=Math.round(design.notchZ*100)+'% of depth';clearTimeout(rebuildTimer);rebuildTimer=setTimeout(rebuild,160);};
$('#slice-button').onclick=()=>{const active=!$('#slice-button').classList.contains('active');$('#slice-button').classList.toggle('active',active);$('#cutaway-control').hidden=!active;viewer.setCutaway(active,+$('#cutaway').value/100);};
$('#cutaway').oninput=e=>viewer.setCutaway(true,+e.target.value/100);

// Stable read-only bridge for future research controllers. All state-changing work remains explicit in the UI.
window.canopyResearch=Object.freeze({
  schemaVersion:1,
  getStatus:()=>({appVersion:'2.2.3',running,solverStatus:state?.status||'preparing',activeExperimentId:resultRecorder.active?.id||null,recordedStates:recording.frames.length,importedReplay:recordingImported,displacementScale:viewer.displacementScale,replayPlaying,replayCursor,replayPending,saving:!!resultRecorder.timer||resultRecorder.pendingSaves>0}),
  listExperiments:async()=>{await resultRecorder.flush();return (await experimentStore.all()).map(({id,name,status,summary,parameters,createdAt,updatedAt})=>({id,name,status,summary,parameters,createdAt,updatedAt}));},
  getExperiment:async id=>{await resultRecorder.flush();return experimentStore.get(id);}
});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')resultRecorder.flush();});
